window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7f89f745274ed36c"]={"versions": [{"id": "FIG-7f89f745274ed36c", "releases": ["R2.1.20", "R3.0.7", "R3.1.5", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) im Kontext der AUTOSAR-Modellpersistenzregeln für XML (AUTOSAR_ModelPersistenceRulesforXML). Das Diagramm veranschaulicht die instanziierte Referenzbeziehung zwischen einem Quellobjekt und mehreren Zielobjekten gemäß Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei anonyme Objektinstanzen:</p>\n<ul class=\"fig-list\"><li><code>:D</code>: Quellinstanz der Klasse <code>D</code> ohne dargestellte Attribute.\n</li><li><code>:B1</code>: Zielinstanz der Klasse <code>B1</code> mit den Attributwerten <code>shortName = instance1</code> und <code>attB1 = someValueB1</code>.\n</li><li><code>:B2</code>: Zielinstanz der Klasse <code>B2</code> mit den Attributwerten <code>shortName = instance2</code> und <code>attB2 = someValueB2</code>.\n</li></ul>\n<p class=\"fig-p\">Verbindungen:</p>\n<ul class=\"fig-list\"><li>Zwei gerichtete Assoziationen (Referenzen) von <code>:D</code> ausgehend, jeweils mit der Rollenbezeichnung <code>+theB</code>: eine führt zu <code>:B1</code>, die andere zu <code>:B2</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanzszenario ohne dynamische Ablauf- oder Zeitsequenzen. Es bildet eine bestehende 1:n- bzw. polymorphe Referenzierungskonfiguration ab, bei der die Instanz <code>:D</code> über die Rolle <code>+theB</code> zeitgleich auf die beiden Entitäten <code>:B1</code> und <code>:B2</code> verweist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als normatives Referenzbeispiel für die XML-Serialisierung und -Persistenz von Modellreferenzen. Ein Element vom Typ <code>D</code> serialisiert die ausgehenden Referenzen unter dem Rollennamen <code>theB</code> auf distinkte Instanzen (<code>instance1</code> vom Typ <code>B1</code> sowie <code>instance2</code> vom Typ <code>B2</code>), wobei die Identifikation der Zielknoten typischerweise über deren <code>shortName</code>-Pfad erfolgt.</p>"}, {"id": "FIG-63b96dbb679b2933", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) im Kontext der AUTOSAR-Modellpersistenzregeln für XML (AUTOSAR_ModelPersistenceRulesforXML). Das Diagramm veranschaulicht die instanziierte Referenzbeziehung zwischen einem Quellobjekt und mehreren Zielobjekten gemäß Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei anonyme Objektinstanzen:</p>\n<ul class=\"fig-list\"><li><code>:D</code>: Quellinstanz der Klasse <code>D</code> ohne dargestellte Attribute.\n</li><li><code>:B1</code>: Zielinstanz der Klasse <code>B1</code> mit den Attributwerten <code>shortName = instance1</code> und <code>attB1 = someValueB1</code>.\n</li><li><code>:B2</code>: Zielinstanz der Klasse <code>B2</code> mit den Attributwerten <code>shortName = instance2</code> und <code>attB2 = someValueB2</code>.\n</li></ul>\n<p class=\"fig-p\">Verbindungen:</p>\n<ul class=\"fig-list\"><li>Zwei gerichtete Assoziationen (Referenzen) von <code>:D</code> ausgehend, jeweils mit der Rollenbezeichnung <code>+theB</code>: eine führt zu <code>:B1</code>, die andere zu <code>:B2</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanzszenario ohne dynamische Ablauf- oder Zeitsequenzen. Es bildet eine bestehende 1:n- bzw. polymorphe Referenzierungskonfiguration ab, bei der die Instanz <code>:D</code> über die Rolle <code>+theB</code> zeitgleich auf die beiden Entitäten <code>:B1</code> und <code>:B2</code> verweist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als normatives Referenzbeispiel für die XML-Serialisierung und -Persistenz von Modellreferenzen. Ein Element vom Typ <code>D</code> serialisiert die ausgehenden Referenzen unter dem Rollennamen <code>theB</code> auf distinkte Instanzen (<code>instance1</code> vom Typ <code>B1</code> sowie <code>instance2</code> vom Typ <code>B2</code>), wobei die Identifikation der Zielknoten typischerweise über deren <code>shortName</code>-Pfad erfolgt.</p>"}], "trans": [{"from": "FIG-7f89f745274ed36c", "to": "FIG-63b96dbb679b2933", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-63b96dbb679b2933", "to": "FIG-7f89f745274ed36c", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
